#pragma once
// Sprint 8 Goal 9: the two embedded OFL faces. They are byte arrays in the exe (src/ui/fonts_embedded/*.h,
// generated by scripts/embed_font.py) so the portable folder stays self-contained -- no font files to lose,
// nothing to install.
#include "raylib.h"

namespace ui
{
    struct Fonts
    {
        Font display{};    // Saira Stencil One: the wordmark and the rail
        Font body{};       // Rajdhani Medium: everything else
        Font bodyBold{};   // Rajdhani SemiBold: headings, values, the buttons
        bool embedded = false;   // false = the stop rule fired and these are raylib's default face
    };

    // Loads the three faces at twice the largest size the design draws at scale 1.0, with bilinear filtering,
    // so they stay sharp wherever the window's scale factor lands. Never fails: if LoadFontFromMemory comes
    // back empty (the spec's stop rule), every face is raylib's default and `embedded` is false.
    Fonts loadFonts();
    void unloadFonts(Fonts &fonts);
}
